    def _eval_power(self, exp):
        """Evaluate powers of a TensorProduct.

        For nonnegative integer exponents we can distribute the power to each
        argument because multiplication of tensor products is component-wise::

            (A⊗B)**n = (A**n)⊗(B**n)

        This allows expressions like ``TensorProduct(A, B)*TensorProduct(A, B)``
        (which SymPy typically rewrites as ``TensorProduct(A, B)**2``) to
        simplify correctly.
        """
        exp = sympify(exp)
        if exp.is_integer and exp.is_nonnegative:
            if exp == 0:
                return S.One
            if exp == 1:
                return self
            return TensorProduct(*[arg**exp for arg in self.args])
        return None

